FLoadoutRow UDeclaredAccessorLibrary::GetLoadoutRow(int32 Key, bool& bFound)
{
    const FLoadoutRow* Found = FDeclaredAccessor::Loadout().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FLoadoutRow();
}

int32 UDeclaredAccessorLibrary::GetLoadoutRowCount()
{
    return FDeclaredAccessor::Loadout().Records().Num();
}

FLoadoutRow UDeclaredAccessorLibrary::GetLoadoutRowAt(int32 Position, bool& bFound)
{
    const TArray<FLoadoutRow>& Rows = FDeclaredAccessor::Loadout().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FLoadoutRow();
}


