bool UDeclaredAccessorLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FDeclaredAccessor::ReadAll(BasePath, FileExtension);
}

bool FDeclaredAccessor::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FLoadoutTable LoadedLoadout;

    if (!LoadedLoadout.Read(FPaths::Combine(BasePath, TEXT("Loadout") + FileExtension)))
    {
        return false;
    }
    FBonusesTable LoadedBonuses;

    if (!LoadedBonuses.Read(FPaths::Combine(BasePath, TEXT("Bonuses") + FileExtension)))
    {
        return false;
    }
    FChestTable LoadedChest;

    if (!LoadedChest.Read(FPaths::Combine(BasePath, TEXT("Chest") + FileExtension)))
    {
        return false;
    }

    LoadoutStorage = MoveTemp(LoadedLoadout);
    BonusesStorage = MoveTemp(LoadedBonuses);
    ChestStorage = MoveTemp(LoadedChest);

    return true;
}
